  3274|async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number, externalSignal?: AbortSignal): Promise<Response> {
  3275|  const controller = new AbortController();
  3276|  const timeoutId = setTimeout(() => {
  3277|    controller.abort(new Error(`Owner AI request timed out after ${timeoutMs}ms`));
  3278|  }, timeoutMs);
  3279|
  3280|  // Forward external aborts (reliability wrapper / watchdog cancel) into the
  3281|  // inner fetch so a hanging socket is cut immediately instead of waiting for
  3282|  // the per-POST timeout — this is the root-cause fix for BACKEND_POST_STARTED
  3283|  // never reaching BACKEND_POST_FINISHED.
  3284|  let externalAbortHandler: (() => void) | null = null;
  3285|  if (externalSignal) {
  3286|    if (externalSignal.aborted) {
  3287|      controller.abort(new Error('Owner AI request aborted by caller before fetch started'));
  3288|    } else {
  3289|      externalAbortHandler = () => {
  3290|        try { controller.abort(new Error('Owner AI request aborted by caller')); } catch { /* noop */ }
  3291|      };
  3292|      externalSignal.addEventListener('abort', externalAbortHandler);
  3293|    }
  3294|  }
  3295|
  3296|  try {
  3297|    return await fetch(url, {
  3298|      ...init,
  3299|      signal: controller.signal,
  3300|    });
  3301|  } catch (error) {
  3302|    if (externalSignal?.aborted) {
  3303|      throw new Error('Owner AI request aborted by caller');
  3304|    }
  3305|    if (error instanceof Error && error.name === 'AbortError') {
  3306|      throw new Error(`Owner AI request timed out after ${timeoutMs}ms`);
  3307|    }
  3308|    throw error;
  3309|  } finally {
  3310|    clearTimeout(timeoutId);
  3311|    if (externalSignal && externalAbortHandler) {
  3312|      try { externalSignal.removeEventListener('abort', externalAbortHandler); } catch { /* noop */ }
  3313|    }
  3314|  }
