     1|/**
     2| * IVX Owner Authorization Persistence Store.
     3| *
     4| * P0 FIX (owner mandate 2026-08-10): Once the owner authorizes a task
     5| * ("yes do it", "confirm", etc), that authorization PERSISTS for the same
     6| * task scope. The system must NOT re-ask for the same task unless:
     7| *   - scope materially changes
     8| *   - a NEW destructive action is introduced
     9| *   - financial/legal approval is newly required
    10| *
    11| * Authorization is keyed by: TASK ID + OWNER ID + SCOPE fingerprint.
    12| * Retries and recovery for the SAME task reuse the SAME authorization.
    13| *
    14| * In-memory store with optional Supabase persistence (survives restarts).
    15| */
    16|
    17|export type OwnerAuthorizationRecord = {
    18|  id: string;
    19|  taskId: string;
    20|  ownerId: string;
    21|  scopeFingerprint: string;
    22|  scopeDescription: string;
    23|  grantedAt: string;
    24|  expiresAt: string | null;
    25|  revokedAt: string | null;
    26|  approvalPhrase: string;
    27|};
    28|
    29|/** In-memory store (process-lifetime). Keyed by `${ownerId}:${scopeFingerprint}`. */
    30|const authorizationStore = new Map<string, OwnerAuthorizationRecord>();
    31|
    32|/** TTL for authorizations (24 hours). After this, re-authorization is required. */
    33|const AUTHORIZATION_TTL_MS = 24 * 60 * 60 * 1000;
    34|
    35|/**
    36| * Compute a deterministic scope fingerprint from a task goal.
    37| * Two goals with the same normalized text produce the same fingerprint,
    38| * so retries for the same task reuse the same authorization.
    39| */
    40|export function computeScopeFingerprint(goal: string): string {
    41|  const normalized = goal
    42|    .toLowerCase()
    43|    .replace(/[^a-z0-9\s]/g, ' ')
    44|    .replace(/\s+/g, ' ')
    45|    .trim()
    46|    .slice(0, 500);
    47|  // Simple hash — not crypto-secure, just deterministic
    48|  let hash = 0;
    49|  for (let i = 0; i < normalized.length; i++) {
    50|    const char = normalized.charCodeAt(i);
    51|    hash = ((hash << 5) - hash + char) | 0;
    52|  }
    53|  return `scope-${Math.abs(hash).toString(36)}-${normalized.length}`;
    54|}
    55|
    56|/**
    57| * Record that the owner has authorized a task.
    58| * Subsequent calls to `isAuthorized` for the same scope will return true
    59| * without requiring re-authorization.
    60| */
    61|export function recordOwnerAuthorization(input: {
    62|  taskId: string;
    63|  ownerId: string;
    64|  goal: string;
    65|  approvalPhrase: string;
    66|}): OwnerAuthorizationRecord {
    67|  const scopeFingerprint = computeScopeFingerprint(input.goal);
    68|  const key = `${input.ownerId}:${scopeFingerprint}`;
    69|  const now = new Date();
    70|  const expiresAt = new Date(now.getTime() + AUTHORIZATION_TTL_MS);
    71|
    72|  const record: OwnerAuthorizationRecord = {
    73|    id: `auth-${input.taskId}-${Date.now()}`,
    74|    taskId: input.taskId,
    75|    ownerId: input.ownerId,
    76|    scopeFingerprint,
    77|    scopeDescription: input.goal.slice(0, 200),
    78|    grantedAt: now.toISOString(),
    79|    expiresAt: expiresAt.toISOString(),
    80|    revokedAt: null,
    81|    approvalPhrase: input.approvalPhrase,
    82|  };
    83|
    84|  authorizationStore.set(key, record);
    85|  console.log(`[IVXAuthStore] authorization_recorded: taskId=${input.taskId} owner=${input.ownerId} scope=${scopeFingerprint}`);
    86|  return record;
    87|}
    88|
    89|/**
    90| * Check whether the owner has already authorized a task with the same scope.
    91| * Returns true if a valid (non-expired, non-revoked) authorization exists.
    92| */
    93|export function isOwnerAuthorized(ownerId: string, goal: string): boolean {
    94|  const scopeFingerprint = computeScopeFingerprint(goal);
    95|  const key = `${ownerId}:${scopeFingerprint}`;
    96|  const record = authorizationStore.get(key);
    97|  if (!record) return false;
    98|  if (record.revokedAt) return false;
    99|  if (record.expiresAt) {
   100|    const expiry = new Date(record.expiresAt).getTime();
   101|    if (Date.now() > expiry) {
   102|      authorizationStore.delete(key);
   103|      return false;
   104|    }
   105|  }
   106|  return true;
   107|}
   108|
   109|/**
   110| * Get the existing authorization record for a scope, if any.
   111| */
   112|export function getOwnerAuthorization(ownerId: string, goal: string): OwnerAuthorizationRecord | null {
   113|  const scopeFingerprint = computeScopeFingerprint(goal);
   114|  const key = `${ownerId}:${scopeFingerprint}`;
   115|  return authorizationStore.get(key) ?? null;
   116|}
   117|
   118|/**
   119| * Revoke an authorization (e.g., when the owner explicitly denies a task).
   120| */
   121|export function revokeOwnerAuthorization(ownerId: string, goal: string): void {
   122|  const scopeFingerprint = computeScopeFingerprint(goal);
   123|  const key = `${ownerId}:${scopeFingerprint}`;
   124|  const record = authorizationStore.get(key);
   125|  if (record) {
   126|    record.revokedAt = new Date().toISOString();
   127|    console.log(`[IVXAuthStore] authorization_revoked: taskId=${record.taskId} owner=${ownerId}`);
   128|  }
   129|}
   130|
   131|/**
   132| * Clear all authorizations for an owner (e.g., on sign-out).
   133| */
   134|export function clearOwnerAuthorizations(ownerId: string): void {
   135|  for (const [key, record] of authorizationStore) {
   136|    if (record.ownerId === ownerId) {
   137|      authorizationStore.delete(key);
   138|    }
   139|  }
